function fresh(){let prices={},stock={};C.forEach((c,i)=>{prices[c.id]={};stock[c.id]={};P.forEach(p=>{prices[c.id][p.id]=Math.round(p.base*p.m[i]);stock[c.id][p.id]=0})});return {name:'Yeni Ufuklar',cash:10000,day:1,prices,previous:JSON.parse(JSON.stringify(prices)),stock,shipments:[],history:[],news:[{day:1,e:'🌱',n:'Ticaret dünyasına hoş geldin!',d:'Piyasalar açıldı. İlk ticaretini yapmaya hazır mısın?'}],event:null,vehicles:{road:0,air:0,sea:0,rail:0},debt:0,warehouse:1,factory:false,sales:0,completed:0,contracts:0,insured:false,analyst:false}}
