function save(){try{localStorage.setItem(V,JSON.stringify(S))}catch{}}function toast(msg){document.getElementById('toastroot').innerHTML=`<div class="toast">${esc(msg)}</div>`;clearTimeout(window.tid);window.tid=setTimeout(()=>document.getElementById('toastroot').innerHTML='',3300)}function log(n,amount=0){S.history.unshift({n,amount,day:S.day});S.history=S.history.slice(0,80)}function cash(delta,n){S.cash+=delta;log(n,delta)}function totalStock(id){return Object.values(S.stock[id]).reduce((a,b)=>a+b,0)}function cap(){return S.warehouse*500}function pending(id){return S.shipments.filter(x=>!x.done&&x.to===id).reduce((a,b)=>a+b.qty,0)}function available(id){return cap()-totalStock(id)-pending(id)}function price(c,p){return S.prices[c][p]}function sellprice(c,p){return Math.max(1,Math.floor(price(c,p)*.96))}function buyprice(c,p){return price(c,p)}function tariff(c){return country(c).tariff*(S.event?.tariff||1)}function active(){return S.shipments.filter(x=>!x.done)}function totalValue(){return C.reduce((a,c)=>a+P.reduce((b,p)=>b+S.stock[c.id][p.id]*sellprice(c.id,p.id),0),0)}function go(v){view=v;render();document.getElementById('content').scrollTop=0; if(document.body.dataset.device==='mobile' && v!=='home' && v!=='map')document.body.classList.add('drawer-open');else document.body.classList.remove('drawer-open');document.body.classList.remove('menu-open')}function openMarket(id){marketCountry=id;warehouseCountry=id;go('market')}function updateTop(){document.getElementById('cash').textContent=fmt(S.cash);document.getElementById('day').textContent='📅 Gün '+S.day;document.getElementById('breadcrumb').textContent=S.name;document.getElementById('level').textContent=1+Math.floor(S.completed/5);document.getElementById('xp').style.width=(S.completed%5*20)+'%';document.getElementById('xptext').textContent=(S.completed%5*80)+'/400 XP';document.getElementById('ticker').textContent=S.news[0].e+' '+S.news[0].n+' — '+S.news[0].d}
function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><div class="muted">${sub}</div></div>${action}</div>`}function card(title,body,action=''){return `<section class="card"><div class="cardhead"><h2>${title}</h2>${action}</div>${body}</section>`}function empty(icon,msg){return `<div class="empty"><span>${icon}</span>${msg}</div>`}function stat(e,l,v){return `<div class="stat"><span class="emoji">${e}</span><div><div class="muted">${l}</div><strong>${v}</strong></div></div>`}function newsList(n=3){return S.news.slice(0,n).map(x=>`<div class="news"><div class="newsicon">${x.e}</div><div><div class="small">Gün ${x.day}</div><b>${x.n}</b><p>${x.d}</p></div></div>`).join('')}
