function mapHTML(){return `<div class="map"><svg viewBox="0 0 900 385" role="img" aria-label="Ticaret dünya haritası"><defs><pattern id="grid" width="45" height="45" patternUnits="userSpaceOnUse"><path d="M 45 0 L 0 0 0 45" fill="none" stroke="#dcebe5" stroke-width=".6"/></pattern></defs><rect width="900" height="385" fill="url(#grid)"/>${LAND.map(d=>`<path class="land" d="${d}"/>`).join('')}${active().map(s=>{let a=country(s.from),b=country(s.to);return `<path class="route" d="M${a.x},${a.y} Q${(a.x+b.x)/2},${Math.min(a.y,b.y)-45} ${b.x},${b.y}"/>`}).join('')}${C.map(c=>`<g class="pin" tabindex="0" role="button" aria-label="${c.n} pazarı" onclick="openMarket('${c.id}')" onkeydown="if(event.key==='Enter')openMarket('${c.id}')"><circle cx="${c.x}" cy="${c.y}" r="11" fill="#b1d7bd" opacity=".7"/><circle cx="${c.x}" cy="${c.y}" r="5.5" fill="#3c9469" stroke="white" stroke-width="2"/><text x="${c.x+(c.id==='TR'?7:10)}" y="${c.y+(c.id==='TR'?-10:4)}">${c.n}</text></g>`).join('')}</svg></div><div class="legend"><span><i class="dot"></i> Ticaret pazarı</span><span>🟠 Aktif sevkiyat rotası</span><span>Bir ülkeye tıklayarak pazara git.</span></div>`}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 250 145" aria-hidden="true"><circle cx="139" cy="72" r="69" fill="#c7e4cd"/><circle cx="139" cy="72" r="52" fill="#f0f6e6" stroke="#8dbda0" stroke-width="1.5"/><ellipse cx="139" cy="72" rx="24" ry="52" fill="none" stroke="#a5c9ab" stroke-width="1.4"/><path d="M88 72h102M97 44h84M97 100h84" stroke="#a5c9ab" fill="none"/><path d="M102 38l15-9 16 6 6 12-10 8-3 14-13-4-7-16zM151 43l20-5 12 14-8 10-14 1-8 13-10-8 3-13zM145 78l19 2 7 14-11 17-10-5-6-17z" fill="#8ebd91"/><path d="M34 111Q124 -8 226 63" fill="none" stroke="#f0ad58" stroke-width="2" stroke-dasharray="5 5"/><g transform="translate(30 80)"><rect width="56" height="42" rx="7" fill="#f1c879"/><path d="M0 12h56M28 0v12" stroke="#d6a451" stroke-width="2"/><rect x="8" y="21" width="16" height="10" rx="2" fill="#fff1cf"/></g><g transform="translate(178 22) rotate(17)"><path d="M0 12l17-2 12-10 5 2-7 10 15 4-1 4-16-1-5 11-4-1 2-12-18-1z" fill="#427d69"/></g><g transform="translate(165 103)"><rect width="63" height="21" rx="5" fill="#4c8e70"/><rect x="42" y="-9" width="21" height="23" rx="4" fill="#6fa687"/><rect x="46" y="-5" width="13" height="9" rx="2" fill="#dfeee3"/><circle cx="13" cy="22" r="6" fill="#36584a"/><circle cx="50" cy="22" r="6" fill="#36584a"/></g></svg>`}
function opportunities(){let arr=[];P.forEach(p=>C.forEach(a=>C.forEach(b=>{if(a.id===b.id)return;let margin=sellprice(b.id,p.id)-buyprice(a.id,p.id)-modeCost('air',a.id,b.id,1,false)-Math.ceil(price(a.id,p.id)*tariff(b.id));arr.push({p,a,b,margin})})));return arr.sort((a,b)=>b.margin-a.margin).slice(0,3)}function oppTable(){return `<div class="tablewrap"><table><thead><tr><th>Ürün</th><th>Rota</th><th>Tahmini kâr / adet*</th><th></th></tr></thead><tbody>${opportunities().map(o=>`<tr><td>${o.p.e} <b>${o.p.n}</b></td><td>${o.a.f} → ${o.b.f} <span class="small">${o.b.n}</span></td><td class="${o.margin>=0?'up':'down'}">${fmt(o.margin)}</td><td><button onclick="openMarket('${o.a.id}')">İncele</button></td></tr>`).join('')}</tbody></table></div><div class="note">* Uçak, mevcut fiyat ve gümrük üzerinden; fiyatlar değişebilir.</div>`}
function home(){return `<div class="hero"><div><div class="tagline">DÜNYA SENİN PAZARIN</div><h1>Merhaba, tüccar! 👋</h1><p>${esc(S.name)} ile dünyaya açıl. Ucuzdan al, doğru pazara gönder, fırsatları yakala.</p><button class="primary" onclick="go('market')">Pazarı keşfet →</button></div>${heroArt()}</div><div class="stats">${stat('💰','Nakit bakiye',fmt(S.cash))}${stat('📦','Depo değeri',fmt(totalValue()))}${stat('🚚','Yoldaki yük',active().length)}${stat('🏆','Tamamlanan sevkiyat',S.completed)}</div><div class="dashboard"><div class="stack">${card('Dünya ticaret haritası',mapHTML(),'<button class="link" onclick="go(\'map\')">Tüm harita →</button>')}${card('Bugünün ticaret fırsatları',oppTable())}</div><div class="stack">${card('Dünya gündemi',newsList(),'<button class="link" onclick="go(\'news\')">Tümü →</button>')}${card('İlk ticaretini yap',`<div class="step"><span>1</span>Pazardan uygun fiyatlı ürün al.</div><div class="step"><span>2</span>Depodan başka ülkeye gönder.</div><div class="step"><span>3</span>Teslim edilince kârla sat.</div><button class="ghost" style="width:100%" onclick="go('warehouse')">Depoma git →</button>`)}${card('Şirket özeti',`<div class="between"><span class="muted">Günlük dönem</span><b>${S.day}. gün</b></div><div class="bar"></div><div class="between"><span class="muted">Toplam satış</span><b>${fmt(S.sales)}</b></div><div class="bar"></div><div class="between"><span class="muted">Banka borcu</span><b>${fmt(S.debt)}</b></div>`)}</div></div>`}
function market(){let c=country(marketCountry);let list=P.filter(p=>(category==='Tümü'||category===p.cat)&&p.n.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')));return heading('Dünya pazarı','Ülke seç, fiyatları karşılaştır, alım satım yap.')+card(c.f+' '+c.n+' pazarı',`<div class="toolbar">${C.map(x=>`<button class="${x.id===c.id?'active':'ghost'}" onclick="marketCountry='${x.id}';render()">${x.f} ${x.n}</button>`).join('')}</div><div class="toolbar"><select aria-label="Kategori" onchange="category=this.value;render()">${['Tümü',...new Set(P.map(p=>p.cat))].map(x=>`<option ${category===x?'selected':''}>${x}</option>`).join('')}</select><input type="search" placeholder="Ürün ara…" value="${esc(search)}" oninput="search=this.value;filterMarket()" aria-label="Ürün ara"><span class="muted">Gümrük: %${Math.round(tariff(c.id)*100)}</span></div><div id="marketrows">${marketRows(list,c)}</div>`)+`<p class="note">Alımlar seçilen ülkenin deposuna gider. Satış sadece o ülkedeki mevcut stoktan yapılır. Alış ve satış fiyatı arasında piyasa makası vardır.</p>`}
function marketRows(list,c){return `<div class="tablewrap"><table><thead><tr><th>Ürün</th><th>Alış / adet</th><th>Satış / adet</th><th>Değişim</th><th>Stok</th><th>İşlem</th></tr></thead><tbody>${list.map(p=>{let prev=S.previous[c.id][p.id],change=(price(c.id,p.id)/prev-1)*100;return `<tr><td><span class="producticon">${p.e}</span><b>${p.n}</b> <span class="small">${p.cat}</span></td><td>${fmt(price(c.id,p.id))}</td><td>${fmt(sellprice(c.id,p.id))}</td><td class="${change<0?'down':'up'}">${change>=0?'+':''}${change.toFixed(1)}%</td><td>${S.stock[c.id][p.id]}</td><td><button onclick="tradeModal('buy','${c.id}','${p.id}')">Al</button> <button class="ghost" ${!S.stock[c.id][p.id]?'disabled':''} onclick="tradeModal('sell','${c.id}','${p.id}')">Sat</button></td></tr>`}).join('')}</tbody></table>${!list.length?empty('🔎','Ürün bulunamadı.'):''}</div>`}function filterMarket(){document.getElementById('marketrows').innerHTML=marketRows(P.filter(p=>(category==='Tümü'||category===p.cat)&&p.n.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr'))),country(marketCountry))}
function modal(title,body){document.getElementById('modalroot').innerHTML=`<div class="modalback" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="cardhead"><h2>${title}</h2><button class="close" onclick="closeModal()" aria-label="Kapat">✕</button></div>${body}</section></div>`}function closeModal(){document.getElementById('modalroot').innerHTML=''}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});function qty(){return Number(document.getElementById('qty').value)}function validq(q){return Number.isInteger(q)&&q>0}function tradeModal(t,c,p){let buying=t==='buy',max=buying?Math.min(available(c),Math.floor(S.cash/buyprice(c,p))):S.stock[c][p];max=Math.max(0,max);modal(product(p).e+' '+product(p).n+(buying?' satın al':' sat'),`<div class="muted">${country(c).f} ${country(c).n} · ${fmt(buying?buyprice(c,p):sellprice(c,p))} / adet</div><div class="field"><label for="qty">Miktar (en fazla ${max})</label><input id="qty" type="number" min="1" max="${max}" value="${Math.min(10,max)}" oninput="tradeQuote('${t}','${c}','${p}')"></div><div class="summary" id="quote"></div><button class="primary" id="confirm" onclick="trade('${t}','${c}','${p}')">${buying?'Satın al':'Satışı tamamla'}</button>`);tradeQuote(t,c,p)}function tradeQuote(t,c,p){let q=qty(),buy=t==='buy',max=buy?Math.min(available(c),Math.floor(S.cash/buyprice(c,p))):S.stock[c][p];document.getElementById('quote').textContent=(buy?'Toplam maliyet: ':'Satış geliri: ')+fmt((validq(q)?q:0)*(buy?buyprice(c,p):sellprice(c,p)));document.getElementById('confirm').disabled=!validq(q)||q>max}function trade(t,c,p){let q=qty(),buy=t==='buy',v=q*(buy?buyprice(c,p):sellprice(c,p));if(!validq(q)||(buy?(q>available(c)||v>S.cash):q>S.stock[c][p]))return toast('Miktarı ve bakiyeni kontrol et.');S.stock[c][p]+=buy?q:-q;cash(buy?-v:v,product(p).n+(buy?' alımı':' satışı')+' · '+country(c).n);if(!buy)S.sales+=v;closeModal();save();render();toast(buy?'📦 Ürünler depoya eklendi.':'💰 Satış tamamlandı!')}
function distance(a,b){let x=country(a),y=country(b);return Math.max(1,Math.hypot(x.x-y.x,x.y-y.y)/140)}function allowed(m,a,b){if(m==='air'||m==='sea')return true;let group=['TR','DE','CN','SA','IN'];return group.includes(a)&&group.includes(b)}function modeCost(m,a,b,q,owned){let f=S.event?.freight||1;if(m==='sea')f*=S.event?.sea||1;return Math.ceil(mode(m).c*distance(a,b)*q*f*(owned?.65:1))}function shippingTime(m,a,b){return Math.ceil(mode(m).s*Math.sqrt(distance(a,b))*(m==='sea'?(S.event?.sea||1):1))}function warehouse(){let c=country(warehouseCountry);return heading('Depolar','Her ülkedeki ürünlerini yönet ve yeni sevkiyat oluştur.')+card(c.f+' '+c.n+' deposu',`<div class="toolbar">${C.map(x=>`<button class="${x.id===c.id?'active':'ghost'}" onclick="warehouseCountry='${x.id}';render()">${x.f} ${x.n}</button>`).join('')}</div><div class="between"><b>Depo kapasitesi</b><span class="muted">${totalStock(c.id)} / ${cap()} adet · ${pending(c.id)} yolda</span></div><div class="progress" style="margin:9px 0 17px"><i style="width:${(totalStock(c.id)+pending(c.id))/cap()*100}%"></i></div>${totalStock(c.id)?`<div class="tablewrap"><table><thead><tr><th>Ürün</th><th>Stok</th><th>Satış değeri</th><th>İşlem</th></tr></thead><tbody>${P.filter(p=>S.stock[c.id][p.id]).map(p=>`<tr><td>${p.e} <b>${p.n}</b></td><td>${S.stock[c.id][p.id]} adet</td><td>${fmt(sellprice(c.id,p.id)*S.stock[c.id][p.id])}</td><td><button class="primary" onclick="shipModal('${c.id}','${p.id}')">Gönder</button> <button class="ghost" onclick="tradeModal('sell','${c.id}','${p.id}')">Sat</button></td></tr>`).join('')}</tbody></table></div>`:empty('📦','Bu depo şu an boş.')}<div class="toolbar" style="margin:15px 0 0"><button class="ghost" onclick="openMarket('${c.id}')">Pazara git</button><button onclick="upgradeWarehouse()">Tüm depoları büyüt · ${fmt(S.warehouse*2500)}</button></div>`)}
function upgradeWarehouse(){let cost=S.warehouse*2500;if(S.cash<cost)return toast('Yetersiz bakiye.');cash(-cost,'Depo kapasitesi artırıldı');S.warehouse++;save();render();toast('📦 Tüm depolara 500 adet kapasite eklendi.')}
function shipModal(a,p){if(!S.stock[a][p])return toast('Bu üründen stok yok.');modal('🚚 Yeni sevkiyat',`<div class="muted">${country(a).f} ${country(a).n} · ${product(p).e} ${product(p).n}</div><div class="field"><label>Varış ülkesi</label><select id="dest" onchange="shipQuote('${a}','${p}')">${C.filter(c=>c.id!==a).map(c=>`<option value="${c.id}">${c.f} ${c.n}</option>`).join('')}</select></div><div class="field"><label>Nakliye yöntemi</label><select id="mode" onchange="shipQuote('${a}','${p}')">${M.map(m=>`<option value="${m.id}">${m.e} ${m.n} · ${m.cap} adet</option>`).join('')}</select></div><div class="field"><label>Miktar (stok: ${S.stock[a][p]})</label><input id="qty" type="number" min="1" max="${S.stock[a][p]}" value="${Math.min(10,S.stock[a][p])}" oninput="shipQuote('${a}','${p}')"></div><label class="row"><input id="insurance" type="checkbox" ${S.insured?'checked':''} onchange="shipQuote('${a}','${p}')"> Taşıma sigortası (%2 ürün değeri)</label><div class="summary" id="quote"></div><button class="primary" id="confirm" onclick="dispatch('${a}','${p}')">Sevkiyatı başlat</button>`);shipQuote(a,p)}
function shipData(a,p){let b=document.getElementById('dest').value,m=document.getElementById('mode').value,q=qty(),insured=document.getElementById('insurance').checked;let owned=(S.vehicles[m]||0)>active().filter(x=>x.mode===m&&x.owned).length;let v=price(a,p)*q,freight=modeCost(m,a,b,q,owned),customs=Math.ceil(v*tariff(b)),insurance=insured?Math.ceil(v*.02):0;return {a,b,m,q,insured,owned,freight,customs,insurance,cost:freight+customs+insurance,time:shippingTime(m,a,b),ok:validq(q)&&q<=S.stock[a][p]&&q<=mode(m).cap&&q<=available(b)&&allowed(m,a,b)}}function shipQuote(a,p){let d=shipData(a,p);document.getElementById('quote').innerHTML=validq(d.q)?`<div class="between"><span>Nakliye ${d.owned?'(kendi aracın)':''}</span><b>${fmt(d.freight)}</b></div><div class="between"><span>Gümrük</span><b>${fmt(d.customs)}</b></div><div class="between"><span>Sigorta</span><b>${fmt(d.insurance)}</b></div><div class="between"><span>Varış süresi</span><b>${d.time} sn</b></div><div class="bar"></div><div class="between"><b>Toplam</b><b>${fmt(d.cost)}</b></div><div class="note">Varışta tahmini satış: ${fmt(sellprice(d.b,p)*d.q)}. ${!allowed(d.m,a,d.b)?'Bu rotada kara/demir yolu kullanılamaz.':!d.ok?'Stok, araç veya depo kapasitesini kontrol et.':''}</div>`:'Geçerli bir miktar gir.';document.getElementById('confirm').disabled=!d.ok||d.cost>S.cash}function dispatch(a,p){let d=shipData(a,p);if(!d.ok||d.cost>S.cash)return toast('Sevkiyat koşullarını kontrol et.');S.stock[a][p]-=d.q;cash(-d.cost,'Sevkiyat · '+country(a).n+' → '+country(d.b).n);let now=Date.now();S.shipments.unshift({id:now+Math.random(),from:a,to:d.b,p,qty:d.q,mode:d.m,owned:d.owned,insured:d.insured,start:now,end:now+d.time*1000,done:false,cost:d.cost});closeModal();save();go('shipping');toast('🚚 Sevkiyat yola çıktı!')}
function shipRows(){let a=active();return a.length?a.map(s=>`<div class="itemcard" style="margin-bottom:10px"><div class="between"><b>${mode(s.mode).e} ${country(s.from).f} ${country(s.from).n} → ${country(s.to).f} ${country(s.to).n}</b><span class="pill yellow" id="time-${s.id}">${Math.max(0,Math.ceil((s.end-Date.now())/1000))} sn</span></div><p>${product(s.p).e} ${s.qty} adet ${product(s.p).n} · ${s.owned?'Kendi filon':'Kiralık nakliye'} ${s.insured?'· Sigortalı':''}</p><div class="progress"><i id="prog-${s.id}" style="width:${Math.min(100,(Date.now()-s.start)/(s.end-s.start)*100)}%"></i></div></div>`).join(''):empty('🚚','Yolda sevkiyat yok. Depodan yeni bir yük gönder.')}
function shipping(){return heading('Sevkiyatlar','Yoldaki yükleri ve tamamlanan teslimatları takip et.','<button class="primary" onclick="go(\'warehouse\')">+ Yeni sevkiyat</button>')+`<div class="stack">${card('Aktif sevkiyatlar ('+active().length+')',shipRows())}${card('Teslimat geçmişi',S.shipments.some(s=>s.done)?`<div class="tablewrap"><table><thead><tr><th>Rota</th><th>Ürün</th><th>Durum</th><th></th></tr></thead><tbody>${S.shipments.filter(s=>s.done).slice(0,30).map(s=>`<tr><td>${country(s.from).f} → ${country(s.to).f} ${country(s.to).n}</td><td>${s.delivered??s.qty} × ${product(s.p).n}</td><td><span class="pill green">Teslim edildi</span></td><td><button onclick="warehouseCountry='${s.to}';go('warehouse')">Depoya git</button></td></tr>`).join('')}</tbody></table></div>`:empty('✅','Henüz teslimat yapılmadı.'))}</div>`}
function tick(){let changed=false;for(let s of active()){if(Date.now()>=s.end){s.done=true;let loss=(!s.insured&&Math.random()<.08)?Math.floor(s.qty*.15):0;s.delivered=s.qty-loss;S.stock[s.to][s.p]+=s.delivered;S.completed++;log('Teslimat · '+country(s.to).n+(loss?' · '+loss+' adet hasarlı':''));changed=true;toast('✅ '+country(s.to).n+' teslimatı tamamlandı'+(loss?' · '+loss+' adet hasarlı.':'!'))}else{let t=document.getElementById('time-'+s.id),p=document.getElementById('prog-'+s.id);if(t)t.textContent=Math.ceil((s.end-Date.now())/1000)+' sn';if(p)p.style.width=Math.min(100,(Date.now()-s.start)/(s.end-s.start)*100)+'%'}}if(changed){save();if(!document.getElementById('modalroot').innerHTML)render()}}
function fleet(){return heading('Nakliye filosu','Kendi araçlarını satın al, nakliye maliyetini düşür.')+`<div class="four">${M.map(m=>`<div class="card itemcard"><div class="big">${m.e}</div><h2>${m.n}</h2><p>${m.cap} adet kapasite · ${m.s} sn temel süre</p><div class="between"><span class="muted">Sahip olunan</span><b>${S.vehicles[m.id]}</b></div><div class="between"><span class="muted">Kullanımda</span><b>${active().filter(s=>s.mode===m.id&&s.owned).length}</b></div><button ${S.cash<m.price?'disabled':''} onclick="buyVehicle('${m.id}')">Satın al · ${fmt(m.price)}</button></div>`).join('')}</div><p class="note">Kendi aracın müsaitse otomatik seçilir ve nakliye maliyetinden %35 tasarruf sağlar. Aracın yoksa kiralık taşıma her zaman kullanılabilir.</p>`}function buyVehicle(m){let v=mode(m);if(S.cash<v.price)return toast('Yetersiz bakiye.');cash(-v.price,v.n+' satın alındı');S.vehicles[m]++;save();render();toast(v.e+' Filona eklendi.')}
function factory(){return heading('Üretim','Hammaddeyi daha değerli ürünlere dönüştür.')+card('🇹🇷 Türkiye · Un fabrikası',`<div class="two"><div class="itemcard"><div class="big">🏭</div><h3>Un fabrikası</h3><p>2 buğday + 3 $ işleme maliyeti → 1 un. Türkiye deposundaki hammaddeleri kullanır.</p><span class="pill ${S.factory?'green':'yellow'}">${S.factory?'Kurulu':'Henüz kurulmadı'}</span>${S.factory?'<button onclick="produceModal()">Üretime başla</button>':'<button onclick="buyFactory()">Fabrika kur · '+fmt(7000)+'</button>'}</div><div class="itemcard"><h3>Hammadde ve ürün</h3><p>🌾 Buğday: ${S.stock.TR.wheat} adet</p><p>🥖 Un: ${S.stock.TR.flour} adet</p><button class="ghost" onclick="openMarket('TR')">Türkiye pazarına git</button></div></div>`)}function buyFactory(){if(S.cash<7000)return toast('Yetersiz bakiye.');cash(-7000,'Un fabrikası kuruldu');S.factory=true;save();render();toast('🏭 Fabrikan hazır!')}function produceModal(){let max=Math.min(Math.floor(S.stock.TR.wheat/2),Math.floor(S.cash/3));modal('🥖 Un üret',`<div class="field"><label>Üretilecek un (en fazla ${max})</label><input id="qty" type="number" min="1" max="${max}" value="${Math.min(5,max)}"></div><button class="primary" onclick="produce()">Üretimi tamamla</button>`)}function produce(){let q=qty();if(!S.factory||!validq(q)||q*2>S.stock.TR.wheat||q*3>S.cash)return toast('Yetersiz hammadde veya bakiye.');S.stock.TR.wheat-=q*2;S.stock.TR.flour+=q;cash(-q*3,'Un üretimi');closeModal();save();render();toast('🥖 '+q+' adet un üretildi.')}
function news(){return heading('Dünya haberleri','Kurgusal olayları takip et; ticaret kararlarını buna göre ver.','<button class="primary" onclick="nextDay()">☀ Yeni güne geç</button>')+`<div class="dashboard"><div class="stack">${card('Haber akışı',newsList(30))}</div><div class="stack">${card('Güncel piyasa etkileri',S.event?`<div class="itemcard"><div class="big">${S.event.e}</div><h3>${S.event.n}</h3><p>${S.event.d}</p>${Object.entries(S.event.products||{}).map(([p,f])=>`<div class="between"><span>${product(p).n}</span><b class="${f>1?'up':'down'}">${f>1?'+':''}${Math.round((f-1)*100)}%</b></div>`).join('')}${S.event.freight?`<p>Nakliye çarpanı: ×${S.event.freight}</p>`:''}${S.event.sea?`<p>Deniz taşımacılığı: ×${S.event.sea}</p>`:''}${S.event.tariff?`<p>Gümrük çarpanı: ×${S.event.tariff}</p>`:''}</div>`:empty('🌤️','Piyasalar normal seyrediyor.'))}${card('Nasıl çalışır?',`<p class="note">Her yeni günde fiyatlar küçük miktarda değişir ve bir kurgusal haber etkisi oluşur. Haberlerin fiyat etkisi kalıcı değil; sonraki gün fiyatlar yeni koşullara göre hesaplanır. Gerçek zamanlı dünya haberleri kullanılmaz.</p>`)}</div></div>`}function nextDay(){if(document.getElementById('modalroot').innerHTML)return;S.day++;S.previous=JSON.parse(JSON.stringify(S.prices));let e=EV[(S.day-2)%EV.length];S.event={...e};S.news.unshift({day:S.day,e:e.e,n:e.n,d:e.d});S.news=S.news.slice(0,40);C.forEach((c,i)=>P.forEach(p=>{let factor=e.products[p.id]||1;S.prices[c.id][p.id]=Math.max(1,Math.round(p.base*p.m[i]*(.96+Math.random()*.08)*factor))}));if(S.debt){let interest=Math.ceil(S.debt*.01);S.debt+=interest;log('Günlük kredi faizi · '+fmt(interest))}save();render();toast('📰 Gün '+S.day+' · '+e.n)}
function finance(){let hist=S.history;return heading('Finans','Nakit, borç ve şirket varlıklarını takip et.')+`<div class="stats">${stat('💵','Nakit',fmt(S.cash))}${stat('📦','Depo varlığı',fmt(totalValue()))}${stat('🏦','Banka borcu',fmt(S.debt))}${stat('📈','Toplam satış',fmt(S.sales))}</div><div class="dashboard"><div class="stack">${card('İşlem geçmişi',hist.length?`<div class="tablewrap"><table><thead><tr><th>Gün</th><th>İşlem</th><th>Tutar</th></tr></thead><tbody>${hist.slice(0,30).map(h=>`<tr><td>${h.day}</td><td>${esc(h.n)}</td><td class="${h.amount>0?'up':h.amount<0?'down':''}">${h.amount?fmt(h.amount):'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('📒','İlk işlemini yaptığında burada görünecek.'))}</div><div class="stack">${card('Banka',`<p class="note">Kredi limiti 25.000 $. Her oyun gününde kalan borca %1 faiz eklenir.</p><div class="between"><span>Mevcut borç</span><b>${fmt(S.debt)}</b></div><div class="bar"></div><button style="width:100%" onclick="loanModal(false)">Kredi çek</button><button style="width:100%;margin-top:8px" class="ghost" onclick="loanModal(true)" ${S.debt<=0?'disabled':''}>Borç öde</button>`)}</div></div>`}function loanModal(pay){let max=pay?Math.min(S.cash,S.debt):Math.max(0,25000-S.debt);modal(pay?'Borç öde':'Kredi çek',`<div class="field"><label>Tutar ($) · En fazla ${fmt(max)}</label><input id="qty" type="number" min="1" max="${max}" value="${Math.min(5000,max)}"></div><button class="primary" onclick="loan(${pay})">Onayla</button>`)}function loan(pay){let q=qty(),max=pay?Math.min(S.cash,S.debt):25000-S.debt;if(!validq(q)||q>max)return toast('Geçerli bir tutar gir.');S.debt+=pay?-q:q;cash(pay?-q:q,pay?'Kredi geri ödemesi':'Banka kredisi');closeModal();save();render();toast('🏦 İşlem tamamlandı.')}
function company(){return heading('Şirketim','Şirket kimliğini ve gelişimini yönet.')+`<div class="two">${card('Şirket profili',`<div class="field"><label>Şirket adı</label><input id="companyname" maxlength="32" value="${esc(S.name)}"></div><button class="primary" onclick="renameCompany()">Kaydet</button><div class="bar"></div><div class="between"><span>Şirket seviyesi</span><b>${1+Math.floor(S.completed/5)}</b></div><p class="note">Her 5 tamamlanan sevkiyatta bir seviye atla.</p><div class="progress"><i style="width:${S.completed%5*20}%"></i></div>`)}${card('Ticaret ayarları',`<div class="between"><div><b>Otomatik sigorta seçimi</b><div class="note">Yeni sevkiyatlarda sigorta önceden seçilsin.</div></div><input aria-label="Otomatik sigorta" type="checkbox" ${S.insured?'checked':''} onchange="S.insured=this.checked;save();toast('Ayar kaydedildi.')"></div><div class="bar"></div><div class="between"><div><b>Depo seviyesi</b><div class="note">Her ülkede ${cap()} adet kapasite</div></div><button onclick="upgradeWarehouse()">Geliştir</button></div><div class="bar"></div><button class="danger" onclick="resetGame()">Oyunu sıfırla</button>`)}</div><div class="card" style="margin-top:16px"><h2>🌱 Geliştirme notları</h2><p class="note">Bu ilk oynanabilir sürüm. Çok oyunculu ekonomi, gerçek haber entegrasyonu, personel, ihaleler, sözleşmeler ve şirket borsası henüz eklenmedi. Yorumlarla birlikte gelişecek!</p></div>`}function renameCompany(){let name=document.getElementById('companyname').value.trim();if(!name)return toast('Bir şirket adı yaz.');S.name=name.slice(0,32);save();render();toast('✨ Şirket adı kaydedildi.')}
function mapView(){return heading('Dünya haritası','Ticaret yaptığın ülkeleri ve sevkiyat rotalarını keşfet.')+card('Küresel ticaret ağı',mapHTML())+`<div class="four" style="margin-top:16px">${C.map(c=>`<div class="card itemcard"><div class="big">${c.f}</div><h3>${c.n}</h3><p>Depo: ${totalStock(c.id)} / ${cap()} · Gümrük %${Math.round(tariff(c.id)*100)}</p><button onclick="openMarket('${c.id}')">Pazarı aç</button></div>`).join('')}</div>`}
function resetGame(){if(confirm('Tüm oyun ilerlemen silinecek. Emin misin?')){S=fresh();marketCountry='TR';warehouseCountry='TR';category='Tümü';search='';save();go('home');toast('🌱 Yeni oyun başlatıldı.')}}
